import { create_list_edit_delete_units } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "UnitDialog",
  props: {
    dialog: Boolean,
    editingUnit: Object
  },
  data() {
    return {
      loading: false,
      unitForm: {
        unit_name: "",
        short_name: ""
      }
    };
  },
  watch: {
    editingUnit: {
      handler(newVal) {
        if (newVal) {
          // Editing mode - populate form with existing data
          this.unitForm = {
            ...newVal
          };
        } else {
          // Add mode - reset form
          this.unitForm = {
            unit_name: "",
            short_name: ""
          };
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
      this.unitForm = {
        unit_name: "",
        short_name: ""
      };
    },
    async save_unit() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        try {
          let result = await API.graphql(graphqlOperation(create_list_edit_delete_units, {
            input: {
              unit_id: this.editingUnit ? this.editingUnit.unit_id : undefined,
              unit_name: this.unitForm.unit_name,
              short_name: this.unitForm.short_name,
              organization_id: data.organization.organization_id,
              action_type: this.editingUnit ? "EDIT" : "CREATE"
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.create_list_edit_delete_units);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.$refs.form.resetValidation();
            this.$refs.form.reset();
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    }
  }
};
